\title{An Effective Exponential Lower Bound for Sub-$\sqrt2$
Vietoris--Rips Approximations}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
The Vietoris--Rips filtration is the central combinatorial object of
topological data analysis, but it is prohibitively large: on $n$ points it can
contain up to $2^n$ simplices. A rich literature builds finitely presented
$c$-approximations---smaller simplicial filtrations that interleave with the
true one up to a multiplicative factor $c\ge 1$ in scale---and these
approximations run into a persistent barrier at the approximation factor
$c=\sqrt2$. We prove that this barrier is intrinsic and we determine its exact
quantitative shape. For every $c\in[1,\sqrt2)$ we exhibit an explicit infinite
family of finite metric spaces $\{X_n\}$---in fact graded ultrametrics with
non-zero distances confined to $[1,\sqrt2]$---such that any one-sided
multiplicative $c$-approximation $G$ of the Vietoris--Rips filtration of $X_n$
satisfies
\[
  \bigl|G(\sqrt2)\bigr| \;\ge\; 2^{\lfloor \gamma(c)\,n\rfloor},
  \qquad \gamma(c)=\frac{\sqrt2/c-1}{\sqrt2-1}.
\]
The rate $\gamma(c)$ is effectively computable, satisfies $0<\gamma(c)\le 1$ on
$[1,\sqrt2)$, equals $1$ at $c=1$, and tends continuously to $0$ as
$c\to\sqrt2^{-}$. Thus the guaranteed exponential rate degrades continuously to
zero exactly at the sharp $\sqrt2$ threshold. The proof bridges metric geometry
(the graded ultrametric), extremal/enumerative combinatorics (a metric clique
of size $m$ forces $2^m$ simplices), and the interleaving theory of
approximation algorithms in topological data analysis.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{The Vietoris--Rips filtration and the size problem}
Let $(X,d)$ be a finite metric space. For a scale parameter $r\ge 0$, the
\emph{Vietoris--Rips complex} $\VR(X;r)$ is the abstract simplicial complex
whose simplices are the finite subsets $S\subseteq X$ of mutually close points:
\[
  S\in\VR(X;r) \iff d(x,y)\le r \text{ for all } x,y\in S.
\]
It is the flag (clique) complex of the graph on $X$ whose edges join pairs at
distance $\le r$. As $r$ increases the complexes nest, forming the
\emph{Vietoris--Rips filtration}, whose persistent homology summarizes the
multi-scale topology of $X$. If the diameter of $X$ is at most $r$, then every
subset of $X$ is a simplex, so $\VR(X;r)$ has $2^{|X|}$ simplices. This
exponential size is the central computational obstacle in applied topology.

\subsection{Finitely presented approximations and the $\sqrt2$ barrier}
A filtration $G(\cdot)$ is a one-sided multiplicative \emph{$c$-approximation}
of $\VR(X;\cdot)$, for $c\ge 1$, when every genuine simplex present at scale $t$
is present in $G$ by scale $c\,t$, and $G$ never contains a simplex absent from
the true filtration by scale $c\,t$:
\[
  \VR(X;t)\subseteq G(c\,t), \qquad G(t)\subseteq \VR(X;c\,t).
\]
Such approximations preserve persistent homology up to a factor $c$. Efficient
approximations exist for factors above $\sqrt2$, while below $\sqrt2$ they break
down. The number $\sqrt2$ is the natural resonance of the construction: the $d$
standard basis vectors of $\RR^d$ are pairwise at distance $\sqrt2$.

\subsection{Contribution}
We prove an effective exponential lower bound valid throughout the
sub-threshold regime, with an explicit computable rate $\gamma(c)$ that governs
the exponent, is positive on all of $[1,\sqrt2)$, equals $1$ at $c=1$, and
vanishes continuously as $c\to\sqrt2^-$.

\section{The graded ultrametric}
We index the $n$ points by $\{0,1,\dots,n-1\}$ and specify pairwise distances
directly.

\begin{definition}[Graded radius]
For $n\ge 1$ and $0\le i<n$, the \emph{radius} of point $i$ is
\[
  \radius(n,i)=1+(\sqrt2-1)\cdot\frac{i+1}{n}.
\]
As $i$ ranges over $0,\dots,n-1$ the radii increase and sweep $(1,\sqrt2]$; the
largest, at $i=n-1$, equals $\sqrt2$.
\end{definition}

\begin{definition}[Graded metric]
The \emph{graded metric} $d_n$ on $X_n$ is $d_n(i,i)=0$ and, for $i\ne j$,
$d_n(i,j)=\radius\bigl(n,\max(i,j)\bigr)$. Every non-zero distance lies in
$[1,\sqrt2]$.
\end{definition}

\begin{lemma}[Radii are $\ge 1$]\label{lem:ge1}
For $n\ge 1$, $\radius(n,i)\ge 1$, since $\sqrt2-1\ge 0$ and $(i+1)/n\ge 0$.
\end{lemma}

\begin{lemma}[Genuine radii are $\le\sqrt2$]\label{lem:le}
For $0\le i<n$, $\radius(n,i)\le\sqrt2$, since $(i+1)/n\le 1$ and
$\sqrt2-1\ge 0$ give $(\sqrt2-1)(i+1)/n\le\sqrt2-1$.
\end{lemma}

\begin{lemma}[Monotonicity]\label{lem:mono}
If $i\le j$ then $\radius(n,i)\le\radius(n,j)$.
\end{lemma}

\begin{proposition}[Metric and ultrametric axioms]
For every $n\ge 1$, $d_n$ is a metric on $X_n$; in fact an ultrametric:
$d_n(i,i)=0$, $d_n(i,j)=d_n(j,i)$, $d_n(i,j)\ge 0$, and
$d_n(i,k)\le\max\{d_n(i,j),d_n(j,k)\}\le d_n(i,j)+d_n(j,k)$.
\end{proposition}
\begin{proof}
The first three properties are immediate from the definition and
Lemma~\ref{lem:ge1}. For the triangle inequality, if $i=k$ it is trivial; if
$i=j$ or $j=k$ it follows by cancelling a zero term; otherwise all points are
distinct, so $d_n(i,j),d_n(j,k)\ge 1$ and their sum is $\ge 2\ge\sqrt2\ge
d_n(i,k)$ by Lemmas~\ref{lem:ge1}--\ref{lem:le}. The strong inequality holds
because $\max(i,k)\le\max\{\max(i,j),\max(j,k)\}$ and $\radius$ is monotone
(Lemma~\ref{lem:mono}).
\end{proof}

\section{From metric cliques to exponentially many simplices}

\begin{definition}[Metric clique]
A subset $S\subseteq X_n$ is a \emph{metric clique at scale $r$} if
$d_n(i,j)\le r$ for all $i,j\in S$; equivalently $S\in\VR(X_n;r)$.
\end{definition}

\begin{proposition}[Clique $\Rightarrow$ full power set]\label{prop:bridge}
If $S$ is a metric clique at scale $r$, then every subset $T\subseteq S$ is a
simplex of $\VR(X_n;r)$; the entire power set of $S$ lies in $\VR(X_n;r)$.
\end{proposition}
\begin{proof}
For $i,j\in T\subseteq S$ we have $d_n(i,j)\le r$, so $T$ is a simplex. This
holds for every $T$ in the power set of $S$.
\end{proof}

\begin{corollary}[Exponential count]\label{cor:count}
A metric clique of size $m$ at scale $r$ forces at least $2^m$ simplices into
$\VR(X_n;r)$.
\end{corollary}

\section{The active set and the effective exponent}

\begin{definition}[Active set]
For $s\ge 0$, the \emph{active set} is $A_n(s)=\{i:\radius(n,i)\le s\}$.
\end{definition}

\begin{lemma}[Active sets are cliques]\label{lem:active}
For every $s$, $A_n(s)$ is a metric clique at scale $s$.
\end{lemma}
\begin{proof}
For distinct $i,j\in A_n(s)$, $d_n(i,j)=\radius(n,\max(i,j))\le s$ because
$\max(i,j)\in A_n(s)$; equal points are at distance $0\le s$.
\end{proof}

\begin{definition}[Effective rate]
For $c\in[1,\sqrt2)$, set $\displaystyle\gamma(c)=\frac{\sqrt2/c-1}{\sqrt2-1}$.
\end{definition}

\begin{proposition}[Radius membership criterion]\label{prop:crit}
For $c\in[1,\sqrt2)$ and $0\le i<n$,
$\radius(n,i)\le\sqrt2/c \iff i+1\le n\,\gamma(c)$.
\end{proposition}
\begin{proof}
$1+(\sqrt2-1)(i+1)/n\le\sqrt2/c$ is equivalent to
$(\sqrt2-1)(i+1)/n\le\sqrt2/c-1$; dividing by $\sqrt2-1>0$ gives
$(i+1)/n\le\gamma(c)$.
\end{proof}

\begin{corollary}[Active count]\label{cor:activecount}
$\bigl|A_n(\sqrt2/c)\bigr|=\min(n,\lfloor n\,\gamma(c)\rfloor)\ge
\lfloor n\,\gamma(c)\rfloor$.
\end{corollary}

\begin{proposition}[Behaviour of the rate]\label{prop:gamma}
On $c\in[1,\sqrt2)$: (1) $\gamma(c)>0$; (2) $\gamma(c)\le 1$ with $\gamma(1)=1$;
(3) $\lim_{c\to\sqrt2^-}\gamma(c)=0$.
\end{proposition}
\begin{proof}
(1) $c<\sqrt2\Rightarrow\sqrt2/c>1$, so the numerator is positive.
(2) $c\ge1\Rightarrow\sqrt2/c\le\sqrt2$, so the numerator is $\le\sqrt2-1$;
equality at $c=1$. (3) As $c\to\sqrt2^-$, $\sqrt2/c\to1$, so the numerator
$\to0$ while the denominator is fixed positive.
\end{proof}

\section{The interleaving lower bound}

\begin{definition}[$c$-approximation]
$G$ is a one-sided multiplicative \emph{$c$-approximation} of $\VR(X_n;\cdot)$
when $c\ge1$ and, for all $t\ge0$, $\VR(X_n;t)\subseteq G(c\,t)$ and
$G(t)\subseteq\VR(X_n;c\,t)$.
\end{definition}

\begin{proposition}[Approximation stores the active power set]\label{prop:store}
Let $c\in[1,\sqrt2)$ and let $G$ be a $c$-approximation. Then the power set of
$A_n(\sqrt2/c)$ is contained in $G(\sqrt2)$, so
$\bigl|G(\sqrt2)\bigr|\ge 2^{|A_n(\sqrt2/c)|}$.
\end{proposition}
\begin{proof}
Set $t=\sqrt2/c$. By Lemma~\ref{lem:active} and Proposition~\ref{prop:bridge},
the power set of $A_n(\sqrt2/c)$ lies in $\VR(X_n;t)$. The approximation gives
$\VR(X_n;t)\subseteq G(c\,t)=G(\sqrt2)$.
\end{proof}

\begin{theorem}[Effective exponential lower bound below $\sqrt2$]
Let $c\in[1,\sqrt2)$ and $n\ge1$, and let $G$ be any $c$-approximation of the
Vietoris--Rips filtration of $X_n$. Then
\[
  \bigl|G(\sqrt2)\bigr|\;\ge\;2^{\lfloor\gamma(c)\,n\rfloor},
  \qquad \gamma(c)=\frac{\sqrt2/c-1}{\sqrt2-1},
\]
where $0<\gamma(c)\le1$ on $[1,\sqrt2)$, $\gamma(1)=1$, and
$\lim_{c\to\sqrt2^-}\gamma(c)=0$.
\end{theorem}
\begin{proof}
By Corollary~\ref{cor:activecount},
$|A_n(\sqrt2/c)|\ge\lfloor\gamma(c)\,n\rfloor$; combine with
Proposition~\ref{prop:store}. The properties of $\gamma$ are
Proposition~\ref{prop:gamma}.
\end{proof}

\begin{remark}[Sharpness]
For fixed $c<\sqrt2$ the bound is exponential in $n$, so no compact
sub-$\sqrt2$ approximation exists. As $c\to\sqrt2^-$ the guaranteed rate
$\gamma(c)\to0$, so the exponential force weakens continuously to nothing
precisely at the threshold; at $c=1$ the rate is $\gamma(1)=1$, recovering the
full $2^n$ blow-up.
\end{remark}

\section{Applications and future work}
Theorem~5.3 is a worst-case guarantee: no algorithm can produce a small
$c$-approximation for all inputs when $c<\sqrt2$. Because $\gamma(c)\to0$ near
$\sqrt2$, the penalty for factors just below the threshold is mild. The proof
isolates a reusable template: design a graded metric whose active window is
tuned by a parameter; observe active sets are cliques; invoke the
clique-to-power-set bridge; pass the count through the interleaving definition.

Future work includes: (1) realising the graded radii by an explicit Euclidean
point cloud (e.g.\ concentric scaled simplices) with the same rate $\gamma(c)$;
(2) extending to two-sided and homotopy interleavings; and (3) determining
whether $\gamma$ is the optimal rate for the graded family and comparing it to
the best known super-$\sqrt2$ algorithms.

\section{Conclusion}
We exhibited an explicit family of finite (ultra)metric spaces on which every
sub-$\sqrt2$ approximation of the Vietoris--Rips filtration must store
$2^{\lfloor\gamma(c)\,n\rfloor}$ simplices, with an effective rate
$\gamma(c)=(\sqrt2/c-1)/(\sqrt2-1)$ that is positive on $[1,\sqrt2)$, equal to
$1$ at the exact filtration, and vanishing continuously at the threshold. This
turns the folkloric $\sqrt2$ barrier into a sharp quantitative theorem.

\end{document}

