"""Demo 1: The graded ultrametric and its distance window.

Builds the graded (ultra)metric d_n on {0,...,n-1},
verifies the metric/ultrametric axioms, and shows that all non-zero
distances live inside [1, sqrt(2)].
"""
from __future__ import annotations
import math
from typing import List

SQRT2: float = math.sqrt(2.0)

def radius(n: int, i: int) -> float:
    return 1.0 + (SQRT2 - 1.0) * (i + 1) / n

def metric_d(n: int, i: int, j: int) -> float:
    return 0.0 if i == j else radius(n, max(i, j))

def verify_ultrametric(n: int) -> bool:
    tol = 1e-12
    for i in range(n):
        if abs(metric_d(n, i, i)) > tol:
            return False
        for j in range(n):
            if abs(metric_d(n, i, j) - metric_d(n, j, i)) > tol:
                return False
            for k in range(n):
                if metric_d(n, i, k) > max(metric_d(n, i, j), metric_d(n, j, k)) + tol:
                    return False
    return True

def distance_window(n: int) -> List[float]:
    return [radius(n, i) for i in range(n)]

if __name__ == "__main__":
    for n in [1, 2, 5, 10, 20]:
        print(f"n={n:3d}: ultrametric axioms hold = {verify_ultrametric(n)}")
    n = 8
    print(f"\\nradii for n={n} (sweep (1, sqrt2]):")
    for i, r in enumerate(distance_window(n)):
        print(f"  radius({n},{i}) = {r:.6f}")
    print(f"largest radius = sqrt(2) = {SQRT2:.6f}")

"""Demo 3: End-to-end effective lower bound below sqrt(2).

Computes gamma(c) = (sqrt2/c - 1)/(sqrt2 - 1), the predicted exponent
floor(gamma(c)*n), and the guaranteed lower bound 2^exponent on the number of
simplices any c-approximation must store at scale sqrt(2). Cross-checks against
the true (full) Vietoris-Rips count 2^n, since the graded metric has diameter
sqrt(2).
"""
from __future__ import annotations
import math
from typing import Tuple

SQRT2: float = math.sqrt(2.0)

def gamma(c: float) -> float:
    return (SQRT2 / c - 1.0) / (SQRT2 - 1.0)

def predicted_exponent(n: int, c: float) -> int:
    return math.floor(gamma(c) * n)

def lower_bound(n: int, c: float) -> int:
    return 2 ** predicted_exponent(n, c)

def report(n: int, c: float) -> Tuple[float, int, int, int]:
    return gamma(c), predicted_exponent(n, c), lower_bound(n, c), 2 ** n

if __name__ == "__main__":
    print(" n    c     gamma   exponent  lower_bound  2^n")
    for n in [4, 6, 8, 10, 20]:
        for c in [1.0, 1.15, 1.3, 1.4]:
            g, e, lb, full = report(n, c)
            assert lb <= full
            print(f"{n:2d}  {c:.2f}  {g:6.4f}  {e:6d}   {lb:10d}  {full}")

