from __future__ import annotations
import math
from typing import List

SQRT2: float = math.sqrt(2.0)

def gamma(c: float) -> float:
    """Effective rate gamma(c) = (sqrt2/c - 1)/(sqrt2 - 1) for c in [1, sqrt2)."""
    if not (1.0 <= c < SQRT2):
        raise ValueError("c must lie in [1, sqrt(2))")
    return (SQRT2 / c - 1.0) / (SQRT2 - 1.0)

def active_clique_size(n: int, c: float) -> int:
    """Number of active vertices at scale sqrt2/c = floor(gamma(c) * n) (capped at n)."""
    return min(n, math.floor(gamma(c) * n))

def active_indices(n: int, c: float) -> List[int]:
    """The active clique: indices 0..k-1 where k = active_clique_size(n, c)."""
    return list(range(active_clique_size(n, c)))

