    require 1 <= c < sqrt(2)
    g <- (sqrt(2)/c - 1) / (sqrt(2) - 1)
    e <- floor(g * n)                          # guaranteed exponent
    return { gamma: g, exponent: e, bound: 2^e }

function VERIFY_BOUND(n, c):
    g <- (sqrt(2)/c - 1) / (sqrt(2) - 1)
    lb <- 2^floor(g * n)
    full <- 0
    for each subset S of {0,...,n-1}:
        if all pairs i,j in S have d_n(i,j) <= sqrt(2):
            full <- full + 1
    return (lb, full, lb <= full)

