from __future__ import annotations
import math
from itertools import combinations
from typing import Tuple

SQRT2: float = math.sqrt(2.0)

def radius(n: int, i: int) -> float:
    return 1.0 + (SQRT2 - 1.0) * (i + 1) / n

def metric_d(n: int, i: int, j: int) -> float:
    return 0.0 if i == j else radius(n, max(i, j))

def vr_complex_size(n: int, r: float) -> int:
    """Brute-force count of Vietoris-Rips simplices at scale r (small n only)."""
    tol = 1e-12
    count = 0
    for size in range(n + 1):
        for S in combinations(range(n), size):
            if all(metric_d(n, i, j) <= r + tol for i in S for j in S):
                count += 1
    return count

def verify_bound(n: int, c: float) -> Tuple[int, int, bool]:
    """Compare predicted lower bound 2^floor(gamma(c)*n) with true count 2^n."""
    g = (SQRT2 / c - 1.0) / (SQRT2 - 1.0)
    lb = 2 ** math.floor(g * n)
    full = vr_complex_size(n, SQRT2)
    return lb, full, lb <= full
